DO $cash_admission$BEGIN IF 'fn_cash_source_refusals_for_period'=ANY(public.fn_ca_guard_watchlist())OR EXISTS(SELECT FROM public.ca_guard_defs WHERE proname='fn_cash_source_refusals_for_period')OR EXISTS(SELECT FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind IN('f','p')AND n.nspname IN('public','smarter_private')AND position('b4ca57c875ff41b0879bcbadc7bcbb63'IN pg_get_functiondef(p.oid))>0)THEN RAISE EXCEPTION 'cash_refusal_active_source_pin';END IF;END$cash_admission$;
